class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for b in range(k + 1):
                dp[i][i][b] = 1
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                diff = abs(ord(s[i]) - ord(s[j]))
                d = min(diff, 26 - diff)
                for b in range(k + 1):
                    best = max(dp[i + 1][j][b], dp[i][j - 1][b])
                    if b >= d:
                        inner = dp[i + 1][j - 1][b - d] if i + 1 <= j - 1 else 0
                        best = max(best, 2 + inner)
                    dp[i][j][b] = best
        return dp[0][n - 1][k]

