class Solution {
    public int longestPalindromicSubsequence(String s, int k) {
        int n = s.length();
        int[][][] dp = new int[n][n][k + 1];
        for (int i = 0; i < n; i++)
            for (int b = 0; b <= k; b++) dp[i][i][b] = 1;
        for (int len = 2; len <= n; len++)
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                int diff = Math.abs(s.charAt(i) - s.charAt(j));
                int d = Math.min(diff, 26 - diff);
                for (int b = 0; b <= k; b++) {
                    int best = Math.max(dp[i + 1][j][b], dp[i][j - 1][b]);
                    if (b >= d) {
                        int inner = (i + 1 <= j - 1) ? dp[i + 1][j - 1][b - d] : 0;
                        best = Math.max(best, 2 + inner);
                    }
                    dp[i][j][b] = best;
                }
            }
        return dp[0][n - 1][k];
    }
}

