var longestPalindromicSubsequence = function(s, k) {
    const n = s.length;
    const dp = Array.from({length: n}, () => Array.from({length: n}, () => new Array(k + 1).fill(0)));
    for (let i = 0; i < n; i++)
        for (let b = 0; b <= k; b++) dp[i][i][b] = 1;
    for (let len = 2; len <= n; len++)
        for (let i = 0; i + len - 1 < n; i++) {
            const j = i + len - 1;
            const diff = Math.abs(s.charCodeAt(i) - s.charCodeAt(j));
            const d = Math.min(diff, 26 - diff);
            for (let b = 0; b <= k; b++) {
                let best = Math.max(dp[i + 1][j][b], dp[i][j - 1][b]);
                if (b >= d) {
                    const inner = (i + 1 <= j - 1) ? dp[i + 1][j - 1][b - d] : 0;
                    best = Math.max(best, 2 + inner);
                }
                dp[i][j][b] = best;
            }
        }
    return dp[0][n - 1][k];
};
